inline constexpr size_t kTableSize = sizeof(kTable) / sizeof(kTable[0]);

inline int32_t Lookup(const char* Name)
{
    if (!Name || !*Name) return 0;
    size_t Lo = 0, Hi = kTableSize;
    while (Lo < Hi) {
        size_t Mid = (Lo + Hi) / 2;
        int Cmp = std::strcmp(Name, kTable[Mid].Name);
        if (Cmp == 0) return kTable[Mid].Index;
        if (Cmp < 0) Hi = Mid;
        else Lo = Mid + 1;
    }
    return 0;
}

inline int32_t LookupW(const wchar_t* Name)
{
    if (!Name || !*Name) return 0;
    std::string Utf8;
    for (const wchar_t* P = Name; *P; ++P) {
        uint32_t cp = (uint32_t)*P;
        if (cp < 0x80) Utf8 += (char)cp;
        else if (cp < 0x800) {
            Utf8 += (char)(0xC0 | (cp >> 6));
            Utf8 += (char)(0x80 | (cp & 0x3F));
        } else if (cp < 0x10000) {
            Utf8 += (char)(0xE0 | (cp >> 12));
            Utf8 += (char)(0x80 | ((cp >> 6) & 0x3F));
            Utf8 += (char)(0x80 | (cp & 0x3F));
        } else {
            Utf8 += (char)(0xF0 | (cp >> 18));
            Utf8 += (char)(0x80 | ((cp >> 12) & 0x3F));
            Utf8 += (char)(0x80 | ((cp >> 6) & 0x3F));
            Utf8 += (char)(0x80 | (cp & 0x3F));
        }
    }
    return Lookup(Utf8.c_str());
}

