inline constexpr size_t kIndexToNameSize = sizeof(kIndexToName) / sizeof(kIndexToName[0]);

inline const char* IndexToName(int32_t Idx)
{
    size_t Lo = 0, Hi = kIndexToNameSize;
    while (Lo < Hi) {
        size_t Mid = (Lo + Hi) / 2;
        if (kIndexToName[Mid].Idx == Idx) return kIndexToName[Mid].Name;
        if (kIndexToName[Mid].Idx < Idx) Lo = Mid + 1;
        else Hi = Mid;
    }
    return "";
}

